{
  "metadata": {
    "send_date": ["1932-10-04"],
    "letter_title": ["Petition for Environmental Protection"],
    "sender_persons": ["Lisa Simpson"],
    "receiver_persons": ["Mayor Joe Quimby", "Seymour Skinner"],
  },
  "content": "Dear Mayor Quimby and Mr. Skinner,\n\nWe, the undersigned, hereby submit a petition to address the environmental degradation caused by the recent construction of the new highway. The noise pollution and air pollution resulting from the increased traffic are adversely affecting the health and well-being of our community. We urge you to take immediate action to mitigate these issues by implementing stricter regulations on vehicle emissions and noise levels. Additionally, we request the planting of more trees and green spaces to help absorb pollutants and provide a healthier environment for our residents. We hope you will consider our concerns and take appropriate measures to protect our community's environment. Thank you for your attention to this matter.",
  "signature": "Sincerely,\nLisa Simpson"
}

